current_day_str = get_current_day()
current_date = datetime.date.fromisoformat(current_day_str)
events = search_calendar_events(query="Yoga Class", date=None)

next_event = None
for event in events:
    event_date = event.start_time.date()
    if event_date >= current_date:
        if next_event is None or event.start_time < next_event.start_time:
            next_event = event

if next_event:
    print(next_event.start_time.strftime('%Y-%m-%d %H:%M'))
else:
    print("No upcoming Yoga Class found.")
